package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="rr_decision_event") public class RrDecisionEvent extends RspAuditedEntity{public enum Type{COMMITTEE_RECOMMENDATION,FINAL_DECISION,RECONSIDERATION_RESOLUTION}public enum Outcome{RECOMMEND,NOT_RECOMMEND,RETURN,DISQUALIFY,APPROVE,DISAPPROVE}@Column(name="evaluation_case_id",nullable=false,length=36)private String evaluationCaseId;@Enumerated(EnumType.STRING)@Column(name="event_type",nullable=false,length=40)private Type eventType;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(name="calculated_score",precision=10,scale=4)private BigDecimal calculatedScore;@Column(name="eligible_voters")private Integer eligibleVoters;@Column(name="attending_voters")private Integer attendingVoters;@Column(name="quorum_met")private Boolean quorumMet;@Column(nullable=false,length=4000)private String reason;@Column(name="decided_by",nullable=false,length=100)private String decidedBy;@Column(name="decided_at",nullable=false)private Instant decidedAt;protected RrDecisionEvent(){}public RrDecisionEvent(String a,String c,Type t,Outcome o,BigDecimal score,Integer eligible,Integer attending,Boolean quorum,String reason,String actor,Instant at){super(a);evaluationCaseId=requiredText(c,"evaluationCaseId");eventType=t;outcome=o;calculatedScore=score;eligibleVoters=eligible;attendingVoters=attending;quorumMet=quorum;this.reason=requiredText(reason,"reason");decidedBy=requiredText(actor,"actor");decidedAt=at;}public String getEvaluationCaseId(){return evaluationCaseId;}public Type getEventType(){return eventType;}public Outcome getOutcome(){return outcome;}public BigDecimal getCalculatedScore(){return calculatedScore;}public Integer getEligibleVoters(){return eligibleVoters;}public Integer getAttendingVoters(){return attendingVoters;}public Boolean getQuorumMet(){return quorumMet;}public String getReason(){return reason;}public String getDecidedBy(){return decidedBy;}public Instant getDecidedAt(){return decidedAt;}}
